WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (711::BIGINT, 'Excelente persona, interesada por el estudiante y tiene todas las clases muy ordenadas, pero para llevar con ella debe de tener cuidado de aprender con los libros y con consulta porque la mitad de lo que entra en los exámenes ni se menciona en la clase pero sí se espera de usted el haberlo aprendido'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '084cdf09f789890a7707d3d290f8a8151fb36879599038c38a841206c4489dae'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Los comentarios que hace y su forma de ser se sienten burlescos y denigrantes, parece que le gusta que uno sufra en el curso. Es muy dura calificando y las instrucciones de bitácoras e informes son muy confusas. Eso sí, vaya a consulta, sí ayuda bastante.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3aba0f5e364cf1b9f9ddc71fbd9eda14c11a6d2ba5dc09e3d769cdc719fcb6a4'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Realmente como persona es muy buena, lo cual ayuda ya que se siente humana y contesta preguntas, el problema es que los aspectos de calificación no están para nada claros, por lo que evalúa de una forma súmamente dura cuando el curso no lo amerita. Pida rúbricas con antelación.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f3f3c57185f26756b55499299ce03a9afe342b5e65519e4df5496b609690b4eb'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Califica más exigente de lo que amerita el aprendizaje del curso, no conozco a los otros profes, pero podría asegurar que no es la mejor opción para matricular'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f63e59ceef59ec6ec54f2c53560e5c99681694ceea20b414482929196ecb79d2'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Explica algunas cosas teóricas importantes antes del laboratorio, lo cual es muy útil incluso para el curso de teoría. Los reportes y bitácoras hay que hacerlas bien hechas y hacer todo lo que pide porque si los califica duro. Los examenes son bastantes sencillos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'c0a60d9783d225356936b0f972d218fc982a4220a5953c00b3075dbeac7d1736'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Excelente calidad de persona, interesada por el estudiante, y tiene orden, pero el que lleve con ella tenga cuidado de aprender con los libros y con consulta porque la mitad de lo que entra en los exámenes ni se menciona en la clase, pero sí se espera de usted el haberlo aprendido.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1a57483c1683808d26cbe51bd1c9e0a73723d2f1d4bc38bdbf1de0ffcc686850'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Es una buena profe. Explica bien la materia, y las clases mejoran si hay un alto grado de participación o si son presenciales (en virtual tiende a ir bastante rápido). Respecto a las evaluaciones califica justamente, y si usted estudia por su cuenta y luego va a consulta el curso se pasa más fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2022-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'c746f047baf21c819d38ca1102afbb05bf15b667dfc0aae12b0a55505f871e23'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'En virtual. La profe explica bien, mas si se tienen que realizar ejercicios independientemente para entender la totalidad de la materia. No tenga miedo de preguntar, poner atencion es clave y si intente llevar la materia al dia. Califica justo segun rubrica. Si le pone, pasa.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2022-01-11T00:00:00+00:00'::TIMESTAMPTZ, '344893804acc5a6e87fcab3be893c8f1be1de119238b5f2db16de7a0c6e07d8f'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Es muy buena gente, le gusta hablar con los estudiantes y las clases no son muy útiles, pero es mejor conectarse. En presencial ha de ser más tuanis, pero en virtual se hizo llevadero, aunque las bitácoras consumen mucho tiempo. La recomiendo como profe, pero sí requiere mucho tiempo fuera de clase'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '49a94e21b76ab1f6c178524017875efc1c3ee010c975c9e1ea0d7412375802f5'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Comprensiva y dispuesta a ayudar, no tiene problema en postergar una entrega si la semana está complicada. Todo el lab en parejas. Da una explicación breve al comienzo de la clase y luego breakout room con su pareja. A pesar de ser virtual ella procura que se tenga algún contacto con los circuitos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '893e8ec1923f25b0ea38a1fe67722ed61707bae2a16c4661545bbc5716b85fa5'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'El curso es bastante útil, se aprende bastante y aunque es rudo la profe está dispuesta a ayudar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '716eabcba0c5e0eca0f6820713160ca419337ded87be44dd30709f193a2557b2'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'La profe califica muy duro, pero también es comprensiva, entonces usted puede hablar con ella para que le ayude si tiene una situación especial. Pará lab de CC y CA es una muy buena profesora.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '807e31f024b5f16fbb85c75aad7cb7d1c0910fe4054fffa71c8f9d7f73fdc882'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Muy buena profe, preocupada por los estudiantes. Le gusta que participen por lo que pregunta mucho durante la clase. Nos reventó en el último examen xd'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '4b1f40e9ad93942123741cdbe00ff4f1feba89c28464b0290741e3d2066d1a5c'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Me sorprende ver comentarios negativos, pero bueno, hablando desde mi experiencia, ha sido de las mejores profes que he tenido, explica DEMASIADO bien, ayuda bastante, se preocupa porque todos aprendan, lo único que pide a cambio es que participen en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '521466267d251926ae29d5db6922783ba53656504a49d4313e8ff3cd2fb755c3'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Es un curso bastante rudo en sí, pero la profe hizo todo lo posible por brindar todo el apoyo que pudiese. Subía muchas guías de estudio para los temas así como prácticas y exámenes viejos al tec digital. Hay que poner mucho de parte de uno para pasar el curso pero la profe alivia mucho la carga.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4c319382ebf10cebc5a7880e1538e60517a45d2ba60647878bee40bbb758935f'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (711::BIGINT, 'Generalmente los exámenes son difíciles, sin embargo para este curso los hizo un poco más fáciles, ya que creo que tuvo empatía por los estudiantes. En el horario de clase(virtual) resuelve dudas y explica aspectos básicos. Para este curso es primordial tener los libros de texto y sus solucionarios.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a381b02b8433cc446fcdd1b3e86fe4e0a13d704054377c3a1c9bc93bd91b9df1'::TEXT, ARRAY[3049]::BIGINT[]),
    (711::BIGINT, 'Este semestre virtual nunca grabó las clases ni las subió. En las clases a veces se dedica a demostrar fórmulas o a leer las presentaciones y medio explicar, ella intenta mucho que uno entienda pero no se le da. Lo mejor es estudiar del libro, ver tutoriales en youtube y preguntarle mucho.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '139e8b396bf1aa444efbabb6294b4e6e29ac4e3fa64e4af71d76eb47c7b38956'::TEXT, ARRAY[3049]::BIGINT[]),
    (711::BIGINT, 'Es un curso muy díficil y la profe intenta dejar bien claro todo lo que puede, a veces se enoja porque uno no entiende un tema simple pero fundamental pero puede dedicar una clase entera solo para explicarlo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '8e41339b7c72b98917e1368fdc91baf5874b5a7e2ea1008e6e739af7d7659dbd'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (711::BIGINT, 'En las clases no explicaba los temas, solo resolvía dudas y mandaba a leer el libro. Si explicaba algo ella sola se enredaba y luego no lo volvía a explicar. Para un examen duró un mes y medio en dar la nota y dura parecido con las notas de las tareas, por lo que uno no sabe en qué falla.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '4808bcada538e41fa2bcc52d960ea2ba80cac122c1c33198c8b207df0da7c780'::TEXT, ARRAY[3049]::BIGINT[]),
    (711::BIGINT, 'Es muy desagradable como persona, con mucha frecuencia trata mal a los estudiantes y es muy pedante, se tarda más tiempo regañando a alguien por preguntar algo "básico" en lugar de dar la explicación requerida. Las clases son malas en su mayoría, es mejor leer el libro (James).'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'e4f1d92c7728d2e373bcae64fbf78195042c48c689aa5f55be96fea79a311cc5'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (711::BIGINT, 'La profe es pura vida y se preocupa por que usted entienda lo que está haciendo. Las pruebas cortas y comprobaciones son fáciles, pero debe dedicarle tiempo a la bitácora porque no deja pasar ningún detalle.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b24274c048861b58bc8b969fbcdd6c13956e5d98f4029cf9a515b8e211825f0a'::TEXT, ARRAY[3050]::BIGINT[]),
    (711::BIGINT, 'Super recomendada. Se nota que quiere que uno aprenda y pase. Para los exámenes cortos, hay que saber un poco de teoría y para las comprobaciones, es de saber hacer cálculos y cómo medir las cosas. El resto es bastante fácil pero hay que dedicarle tiempo, especialmente a bitácoras y reportes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '559002c7ff88e7e31c88fc2e275545c38983ebed94bf0820b0ce24f57787b21c'::TEXT, ARRAY[927, 3050]::BIGINT[]),
    (711::BIGINT, 'Las comprobaciones no son fáciles, pero lo demás lo ayuda a uno a pasar. En realidad la materia es muy fácil, pero hay que dedicarle mucho tiempo a las bitácoras y reportes'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '40f31a3f87ae8008623d3c936b335aac6e52b59d0f97869e1976b1013c7546bf'::TEXT, ARRAY[927, 3050]::BIGINT[]),
    (711::BIGINT, 'Solo llega a leer las presentaciones y a demostrar fórmulas. Después de los primeros quices te das cuenta de que las clases no sirven para nada, ya que no se hacen ejercicios y el nivel de dificultad es muy alto. Como persona es muy desagradable y trata mal a los estudiantes con regularidad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '88fe6bdac0173583cb8cd8a863951777117cdedca6d25d241030f2ff9158addf'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (711::BIGINT, 'Mala. Y creo que tiene un romance con Chocobola..eeeeyyyy'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-07-14T00:00:00+00:00'::TIMESTAMPTZ, '649555d316edde6e5a5c7577c87a19ba2a9652e048b41188e3a6bf71dccd89a0'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Análisis no es pesado, pero cuesta entenderle a la profe. Casi no paso, pero me dio una oportunidad, creo q fue porque vio que le ponia en clases.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd1e3803004ba0a242f68d8f1c8f9f034a48b80a808b2a529ec06769534b4e6c6'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Se le entiende un poco más que en modelos pero igual hay que ser autodidacta'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3333298d8c821f9461a85ef28ec331044836ec9e393e52ab712869f18e431f75'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Sirve ver los videos de Pablo antes de la clase, así le entiende mejor a la profe, aprovecha más la clase, y puede aclarar más dudas. De otra forma no se le entiende. Es bueno participar en clases y hacer los ejercicios que deja. Es mejor prepararse muy bien para los exámenes, son difíciles.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'a6ab733ecca7b05c80c70e7e04e4688dec09a72f6d7b13063b2f76cebc4dff7d'::TEXT, ARRAY[3057]::BIGINT[]),
    (711::BIGINT, 'Es pésima profe, no se entiende nada y la profe solo le genera ganas de dormir, es pedante y muy mala con el sarcasmo... Mejor leer el libro y ver los videos, y obviamente practicar mucho.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-05T00:00:00+00:00'::TIMESTAMPTZ, '24b93b485dc9b76f30c717e566174bfa95b475b3bf95bf04b2625d6741b9af07'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (711::BIGINT, 'En si el curso es muy duro y se le entiende muy poco cuando explica, hay que pasar viendo los videos de pablo y estudiando del libro.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'c1e3c19b1af7e0c6e646a4c30ff0caa4f3984764306b54dfac5fadb9979e6cbd'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (711::BIGINT, 'Se nota que ama el curso y hace todo lo posible para que uno entienda. Muy buena en horas de consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2017-08-20T00:00:00+00:00'::TIMESTAMPTZ, '4f9c4f40eb5c1e7c82e8230a0e7e6b748963020b43609ceffd839f92b30437ab'::TEXT, ARRAY[3064]::BIGINT[]),
    (711::BIGINT, 'Es más que claro que anda con el profe Díaz (chocobola)...si quiere pasar sólo hablele bien de Díaz..ja ja ja'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2017-08-10T00:00:00+00:00'::TIMESTAMPTZ, '37174ce418dd11f71bc704fc6d94fe4237e9fef3a10e03000c08ffd54eb97641'::TEXT, ARRAY[3057]::BIGINT[]),
    (711::BIGINT, 'El curso solo tiene dos exámenes y no son fáciles... Nunca le entendí nada a la profe por más que le ponía atención; sin embargo, ella domina demasiado bien la materia y cualquier duda se la responde, pero no aseguro que entienda la explicación. Es bueno participar en clase'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1c3d810041943e322b962477266966906df7f5a8114b5c5b1a2b82ae74278ec8'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (711::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3e6c6a324fcfc16b6cb81e87e9fb1b2e64f96f98e72ecc1acaf800cf08e47140'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
